interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  compiledValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private registerDynamic(definition: () => ToolDefinition, execute: ToolExecutor): void {
    const resolved = definition();
    getDynamicValidator(resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    if (typeof definition === 'function') {
      this.registerDynamic(definition, execute);
      return;
    }
    const compiledValidator = compileSchema(definition.name, definition.inputSchema);
    this.tools.set(definition.name, {definitionSource: definition, execute, compiledValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = this.validatorFor(name, tool);
    if (!validator(input)) {
      return rejectInvalidInput(name, validator.errors);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private validatorFor(name: string, tool: StoredTool): ValidateFunction {
    if (tool.compiledValidator) {
      return tool.compiledValidator;
    }
    const resolved = this.resolveDefinition(tool.definitionSource);
    return getDynamicValidator(name, resolved.inputSchema);
  }
}

const ajv = new ajvModule.default({strict: false, validateFormats: false, allErrors: true});
const dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

function getDynamicValidator(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  const cached = dynamicValidators.get(schema);
  if (cached) {
    return cached;
  }
  const compiled = compileSchema(toolName, schema);
  dynamicValidators.set(schema, compiled);
  return compiled;
}

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`, {cause: error});
  }
}

function rejectInvalidInput(toolName: string, errors: ErrorObject[] | null | undefined): ToolResponse {
  const validationErrors = errors ?? [];
  const failures = validationErrors.map(describeFailure);
  log.warn('tool', 'input validation failed', {name: toolName, failures});
  return {result: `Invalid input for tool "${toolName}": ${ajv.errorsText(validationErrors, {dataVar: 'input'})}`};
}

function describeFailure(error: ErrorObject): {path: string; keyword: string} {
  const missingProperty: unknown = error.params.missingProperty;
  const suffix = typeof missingProperty === 'string' ? `/${missingProperty}` : '';
  return {
    path: `${error.instancePath}${suffix}` || '/',
    keyword: error.keyword,
  };
}

